sys_script_include.script:
var FeedbackUtils = Class.create();
FeedbackUtils.prototype = {
    initialize: function() {},

    // 1. Fetch feedback details by ID (feedback number)
    getFeedbackByID: function(feedbackID) {
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('number', feedbackID);
        gr.query();
        if (gr.next()) {
            return gr.getDisplayValue( 'u_attendee_id')+ ' | ' + gr.u_rating + ' | ' + gr.u_comments;
        }
        return 'No feedback found';
    },

    // 2. Check if feedback is positive (Excellent or Good)
    isPositiveFeedback: function(feedbackID) {
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('number', feedbackID);
        gr.query();
        if (gr.next()) {
            var rating = gr.u_rating.toLowerCase();
            if (rating === 'excellent' || rating === 'good') {
                return 'Positive Feedback';
            } else {
                return 'Not Positive';
            }
        }
        return 'Feedback not found';
    },

    // 3. Fetch all feedback entries by Event ID
    getFeedbackByEvent: function(eventID) {
        var gr = new GlideRecord('x_1790227_event_ma_feedback');
        gr.addQuery('u_event_id.number', eventID);
        gr.query();
        var result = [];
        while (gr.next()) {
            result.push(gr.getDisplayValue('u_attendee_id') + ' | ' + gr.u_rating + ' | ' + gr.u_comments);
        }
        return result.length ? result.join('\n') : 'No feedback found';
    },

    type: 'FeedbackUtils'
};
